import{_ as t,o,c as r,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"历境炼心","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-历境炼心.md","filePath":"10-核心模型/model-历境炼心.md","lastUpdated":1778031108000}'),e={name:"10-核心模型/model-历境炼心.md"};function i(n,a,s,h,u,d){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="历境炼心" tabindex="-1">历境炼心 <a class="header-anchor" href="#历境炼心" aria-label="Permalink to &quot;历境炼心&quot;">​</a></h1><blockquote><p>了空居士智慧体系的实践修行。 在每一个细节上磨炼，一切境遇都是修行的机会。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>历境炼心</strong> 是了空居士教导中&quot;修行落地&quot;的核心。修行不是在蒲团上完成的，而是在 <strong>每一个生活细节、每一件具体事情</strong> 中完成的。烦恼就是菩提，逆缘就是助缘。</p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-细致圆满" tabindex="-1">1. 细致圆满 <a class="header-anchor" href="#_1-细致圆满" aria-label="Permalink to &quot;1. 细致圆满&quot;">​</a></h3><p><strong>原文</strong>：大圣人的一切行为都是那么了了分明，都是那么的细致。</p><p><strong>解读</strong>：从释迦牟尼佛托钵的细节——穿袈裟、洗脚、铺坐垫——看出真正的修行就在这些细枝末节里。细致就是修行，圆满就是功夫。</p><h3 id="_2-恭敬心" tabindex="-1">2. 恭敬心 <a class="header-anchor" href="#_2-恭敬心" aria-label="Permalink to &quot;2. 恭敬心&quot;">​</a></h3><p><strong>原文</strong>：世尊著衣持钵…对大众都很恭敬。</p><p><strong>解读</strong>：释迦牟尼佛去托钵，都要穿上最好的衣服（袈裟），恭敬地面对每一个布施者。恭敬不是卑微，是尊重一切众生。</p><h3 id="_3-平等心" tabindex="-1">3. 平等心 <a class="header-anchor" href="#_3-平等心" aria-label="Permalink to &quot;3. 平等心&quot;">​</a></h3><p><strong>原文</strong>：世尊批评大迦叶和须菩提，要以平等心去次第托钵。</p><p><strong>解读</strong>：大迦叶专找穷人托钵（想给他们种福田），须菩提专找富人托钵（不想让穷人破费）。世尊说：都不对。要以平等心次第而行。</p><h3 id="_4-随喜即众善" tabindex="-1">4. 随喜即众善 <a class="header-anchor" href="#_4-随喜即众善" aria-label="Permalink to &quot;4. 随喜即众善&quot;">​</a></h3><p><strong>原文</strong>：随喜是众善奉行的第一步。</p><p><strong>解读</strong>：看到别人做好事，心生欢喜，这就是随喜。不要嫉妒，不要麻木，欢喜他人的功德，就是种下自己的善根。</p><h3 id="_5-不怕念起-只怕觉迟" tabindex="-1">5. 不怕念起，只怕觉迟 <a class="header-anchor" href="#_5-不怕念起-只怕觉迟" aria-label="Permalink to &quot;5. 不怕念起，只怕觉迟&quot;">​</a></h3><p><strong>原文</strong>：不怕念起，只怕觉迟。</p><p><strong>解读</strong>：有杂念没关系，关键是能不能及时觉察到。能觉察到，你就已经在修行了。没有念头的是木头人。</p><h3 id="_6-因果分条算" tabindex="-1">6. 因果分条算 <a class="header-anchor" href="#_6-因果分条算" aria-label="Permalink to &quot;6. 因果分条算&quot;">​</a></h3><p><strong>原文</strong>：念佛的功德和造业的果报各算各的。</p><p><strong>解读</strong>：不是说我念佛了就不受恶报，也不是说造了业念佛就没用。因果是&quot;一条一条算&quot;的——种善因得善果，造恶业得恶果，互不抵消。但修行可以转重业为轻受。</p><h3 id="_7-烦恼即菩提" tabindex="-1">7. 烦恼即菩提 <a class="header-anchor" href="#_7-烦恼即菩提" aria-label="Permalink to &quot;7. 烦恼即菩提&quot;">​</a></h3><p><strong>原文</strong>：一切烦恼为如来种。</p><p><strong>解读</strong>：有烦恼才有觉悟的机会。维摩诘说&quot;一切烦恼为如来种&quot;——如同莲花生于淤泥，觉悟生于烦恼。大迦叶这些&quot;沉空守寂&quot;的人，反而比有烦恼的众生更难觉悟。</p><h3 id="_8-开悟与悟后迷" tabindex="-1">8. 开悟与悟后迷 <a class="header-anchor" href="#_8-开悟与悟后迷" aria-label="Permalink to &quot;8. 开悟与悟后迷&quot;">​</a></h3><p><strong>原文</strong>：开悟很容易，悟后迷也同样的容易！</p><p><strong>解读</strong>：可能刹那间明白了&quot;应无所住&quot;，但一转身遇到具体事又迷了。修行不是追求&quot;开悟&quot;那一刻，而是要在日常生活中持续地&quot;不离这个&quot;。悟后迷可以用&quot;信、愿、行&quot;来克服。</p><h3 id="_9-保持平静的窍诀" tabindex="-1">9. 保持平静的窍诀 <a class="header-anchor" href="#_9-保持平静的窍诀" aria-label="Permalink to &quot;9. 保持平静的窍诀&quot;">​</a></h3><p><strong>原文</strong>：保持平静的要诀就是保持理智地去看待一切。</p><p><strong>解读</strong>：不平静的时候问自己：&quot;我为什么要不平静？这样的不平静正确吗？&quot;韩信能忍胯下之辱，是因为理智告诉他&quot;不忍后果更严重&quot;。理智就是历境炼心的工具。</p><h3 id="_10-愿力决定层次" tabindex="-1">10. 愿力决定层次 <a class="header-anchor" href="#_10-愿力决定层次" aria-label="Permalink to &quot;10. 愿力决定层次&quot;">​</a></h3><p><strong>原文</strong>：同样是无诤三昧，发大愿和没有发大愿，深度不一样。</p><p><strong>解读</strong>：如同两把一样的铁锤，一把轻敲一把重击，效果不同。修行境界一样，但有没有大愿力决定了能发挥多大的作用。普贤菩萨&quot;虚空界尽，我愿乃尽&quot;——大愿力让修行者不满足于&quot;自了&quot;，而是不断地利益众生。</p><h3 id="_11-顺逆皆修" tabindex="-1">11. 顺逆皆修 <a class="header-anchor" href="#_11-顺逆皆修" aria-label="Permalink to &quot;11. 顺逆皆修&quot;">​</a></h3><p><strong>原文</strong>：在顺境里修炼是基础功，还要在逆境中修炼到心如如不动，功夫才是真的。</p><p><strong>解读</strong>：风和日丽的时候谁都能静心，但风雨交加时还能保持清净心，那才是真功夫。不是特意去危险的地方，而是要修炼到无论顺逆都能&quot;若见诸相非相&quot;。</p><h3 id="_12-冤亲平等" tabindex="-1">12. 冤亲平等 <a class="header-anchor" href="#_12-冤亲平等" aria-label="Permalink to &quot;12. 冤亲平等&quot;">​</a></h3><p><strong>原文</strong>：初级修炼要和亲人恩人一起修，调出感恩心；功夫深了要和仇人一起修，从恨修到原谅甚至同情。</p><p><strong>解读</strong>：修行不是只挑好人相处。最难修的是面对你不喜欢的人时还能保持平等心。但这恰恰是&quot;历境炼心&quot;最有效的地方——通过实际的逆境来磨炼心性。</p><h3 id="_13-放下屠刀立地成佛" tabindex="-1">13. 放下屠刀立地成佛 <a class="header-anchor" href="#_13-放下屠刀立地成佛" aria-label="Permalink to &quot;13. 放下屠刀立地成佛&quot;">​</a></h3><p><strong>原文</strong>：放下屠刀，立地成佛。刹那间心转过来，那个状态就是佛。</p><p><strong>解读</strong>：不是说放下屠刀后就慢慢修成佛，而是放下屠刀的当下，你的心已经转变了。一念觉就是佛，一念迷就是凡夫。当然大根器的人一悟永悟，小根器的人还会反复。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>态度上</strong>：</p><ul><li>把每一天遇到的每一件事都当作修行的机会</li><li>好事来了不起贪心，坏事来了不起嗔心</li><li>不把修行和生活割裂，生活就是道场</li></ul><p><strong>具体做法</strong>：</p><ul><li>工作中认真负责，这就是修行——历境炼心</li><li>与人相处时保持恭敬，这就是修行——历境炼心</li><li>遇到困难不逃避、不抱怨，这就是修行——历境炼心</li><li>被人冤枉时不立刻发火，先问问自己&quot;为什么会这样&quot;——历境炼心</li><li>每天做一点善事，但不求回报，这就是历境炼心</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 历境炼心的心态基础</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 历境炼心的方法指导</li><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 历境炼心的身体实践</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会因由分）</li><li>金刚经第2分（善现启请分）</li><li>金刚经第3分（大乘正宗分）</li><li>金刚经第5分（如理实见分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第9分（一相无相分）</li><li>金刚经第11分（无为福胜分）</li><li>金刚经第16分（能净业障分）</li><li>金刚经第17分（究竟无我分）</li><li>金刚经第18分（一体同观分）</li><li>金刚经第23分（净心行善分）</li><li>金刚经第25分（化无所化分）</li><li>答疑专辑2014/2019</li><li>处世系列</li><li>六祖法宝坛经</li></ul><blockquote><p>来源：<a href="/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a>、<a href="/03_答疑专辑2014_佛道">03_答疑专辑2014_佛道</a> 蒸馏日期：2026-05-05（第一版）2026-05-06（第二版，共13原子）</p></blockquote>',58)])])}const g=t(e,[["render",i]]);export{q as __pageData,g as default};
